import { defineConfig } from "vite";

// Separate build for the Zoom embed page (NOT part of the main TanStack app).
//
// Why this exists: public/zoom-embed.html runs inside an <iframe> with NO
// React, so the Meeting SDK (which pins React 18, while the app is on
// React 19) boots cleanly there. But files in public/ are copied verbatim —
// a `<script src="/src/...">` works in dev yet 404s in production. This
// config pre-bundles src/zoom-embed/zoom-embed.ts (+ the SDK + its own React
// copy) into ONE self-contained file at public/zoom-sdk/zoom-embed.bundle.js,
// which the main `vite build` then copies to dist/ like any public asset.
//
// Usage:
//   npm run build:zoom-embed   (runs automatically as part of `npm run build`)
// Re-run it after upgrading @zoom/meetingsdk. Devs need it once — the bundle
// persists in public/zoom-sdk/ (git-ignored) and the dev server serves it.
export default defineConfig({
  build: {
    // Do NOT copy public/ into the outDir (outDir lives inside public/).
    copyPublicDir: false,
    emptyOutDir: true,
    minify: true,
    lib: {
      entry: "src/zoom-embed/zoom-embed.ts",
      name: "ZoomEmbed",
      formats: ["iife"],
      fileName: () => "zoom-embed.bundle.js",
    },
    outDir: "public/zoom-sdk",
    // Inline small assets; the SDK loads its heavy AV/WASM payloads from its
    // CDN at runtime, so nothing else needs shipping.
    assetsInlineLimit: 4096,
  },
});

