var client = NS.createClient();
// Report camera state so the parent popup can nudge HR when all
// video is off (an all-black stage means no feeds, not a bug).
function reportVideo(users) {
  try {
    var list = Array.isArray(users)
      ? users
      : users && users.users
        ? users.users
        : [users];
    var anyOn = list.some(function (u) {
      return (
        !!u &&
        (u.bVideoOn === true ||
          u.videoOn === true ||
          u.isVideoOn === true)
      );
    });
    parent.postMessage({ zoomVideoOn: anyOn }, "*");
  } catch (e) {
    /* ignore */
  }
}
try {
  if (typeof client.on === "function") {
    client.on("user-added", reportVideo);
    client.on("user-updated", reportVideo);
  }
} catch (e) {
  /* older SDK without events — parent simply never gets the hint */
}

