// Size the video stage to whatever this iframe actually is. The
            // parent sizes the iframe to its pane, so the iframe window size
            // IS the pane size — no hardcoded 800x450 that leaves a black
            // letterbox whenever the dialog is a different shape.
            // ~52px is reserved for the SDK toolbar it renders at the top.
            var TOOLBAR_H = 52;
            var w = Math.max(320, Math.round(window.innerWidth));
            var h = Math.max(200, Math.round(window.innerHeight) - TOOLBAR_H);
            client
              .init({
                zoomAppRoot: root,
                language: "en-US",
                patchJsMedia: true,
                leaveOnPageUnload: true,
                customize: {
                  video: {
                    // Auto-resize with the pane: without it the stage is
                    // user-draggable and can drift away from the container.
                    isResizable: false,
                    // Size BOTH layouts to the pane: with one participant the
                    // SDK uses the ribbon filmstrip, with more it uses the
                    // default (gallery/speaker) stage.
                    viewSizes: {
                      ribbon: { width: w, height: h },
                      default: { width: w, height: h },
                    },
                    defaultViewType: "speaker",
                  },
                },
              })

